export const getPlaceholder = (src) => {
  if (!src || typeof src !== 'string') return null;
  const clean = src.replace(/^\.\//, '').replace(/^public[\\\/]/, '').replace(/\\/g, '/');
  for (const [k, v] of Object.entries(IMAGE_PLACEHOLDERS)) {
    const kClean = k.replace(/^public[\\\/]/, '').replace(/\\/g, '/');
    if (kClean === clean || k === src) return v;
  }
  return null;
};
